// ===== AJUSTES =====
const EMPRESA = 'Tu empresa';
// ===================

const esc = (t) => String(t ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const euros = (n) => Number(n || 0).toLocaleString('es-ES', { minimumFractionDigits: 2, maximumFractionDigits: 2 }) + ' €';
const lista = (xs, f) => (xs || []).map(f).filter(Boolean).join(' · ');

return $input.all().map((item) => {
  const { parte: p, archivo, pdfBase64 } = item.json.body;
  const c = p.cliente || {};
  const firmante = p.responsable ? `${p.responsable.nombre} (DNI ${p.responsable.dni})` : c.nombre;
  const mats = lista(p.materiales, (m) => [m.cant, m.desc].filter(Boolean).join(' '));
  const mano = lista(p.manoObra, (m) => [m.desc, m.horas ? m.horas + ' h' : ''].filter(Boolean).join(' '));
  const total = p.totales?.hay ? euros(p.totales.total) : 'sin importe (lo pone la oficina)';

  const htmlCliente = `<p>Hola:</p>
<p>Le enviamos el albarán <b>Nº ${esc(p.numero)}</b> del trabajo realizado el ${esc(p.fechaTexto)}, firmado por ${esc(firmante)}.</p>
<p>Lo tiene adjunto en PDF. Cualquier duda, responda a este correo.</p><p>Un saludo,<br>${esc(EMPRESA)}</p>`;

  const htmlOficina = `<p><b>Parte Nº ${esc(p.numero)}</b> · ${esc(p.fechaTexto)} ${esc(p.hora)} · ${esc(p.trabajador)}</p>
<table cellpadding="4">
<tr><td><b>Cliente</b></td><td>${esc(c.nombre)} · ${esc(c.nif)}</td></tr>
<tr><td><b>Dirección</b></td><td>${esc(c.calle)}, ${esc(c.localidad)}</td></tr>
<tr><td><b>Trabajo</b></td><td>${esc(p.trabajo)}</td></tr>
<tr><td><b>Materiales</b></td><td>${esc(mats)}</td></tr>
<tr><td><b>Mano de obra</b></td><td>${esc(mano)}</td></tr>
<tr><td><b>Total</b></td><td>${esc(total)}</td></tr>
<tr><td><b>Firmado por</b></td><td>${esc(firmante)}</td></tr>
</table><p>Albarán firmado adjunto. Listo para facturar.</p>`;

  const telegram = `<b>📄 Parte Nº ${esc(p.numero)} firmado</b>\n${esc(c.nombre)} · ${esc(c.localidad)}\n${esc(p.trabajador)} · ${esc(p.fechaTexto)} ${esc(p.hora)}\n<b>Total:</b> ${esc(total)}\n<i>Firmado por ${esc(firmante)}</i>`;

  const fila = {
    'Nº': p.numero, 'Fecha': p.fecha, 'Hora': p.hora, 'Trabajador': p.trabajador, 'Cliente': c.nombre, 'NIF/CIF': c.nif,
    'Localidad': c.localidad, 'Trabajo': p.trabajo, 'Materiales': mats, 'Mano de obra': mano,
    'Total': p.totales?.hay ? Number(p.totales.total.toFixed(2)) : '', 'Firmado por': firmante, 'Origen': 'Parte digital', 'Facturado': '',
  };
  return { json: { numero: p.numero, emailCliente: c.email || '', asuntoCliente: `Albarán Nº ${p.numero} · ${EMPRESA}`, htmlCliente,
    asuntoOficina: `Parte Nº ${p.numero} · ${c.nombre} · listo para facturar`, htmlOficina, telegram, fila, archivo, pdfBase64 } };
});

// Coge la foto que se ha subido y se la manda a Gemini para que la lea
const instrucciones = `Esta foto es un PARTE DE TRABAJO de una empresa de instalaciones eléctricas, rellenado a mano.
Puede estar girada. Lee lo escrito a mano y devuelve SOLO un JSON con esta forma:
{"numero":"","fecha":"","cliente":"","nif":"","calle":"","localidad":"","telefono":"",
 "materiales":[{"cant":"","descripcion":"","referencia":"","importe":""}],
 "mano_obra":[{"codigo":"","descripcion":"","horas":"","importe":""}],
 "dudas":""}
Reglas:
- Copia lo que pone; puedes corregir abreviaturas obvias de material eléctrico (mt = metros, "tuercas" etc.).
- Si algo no se lee bien, ponlo igualmente y explícalo en "dudas". No inventes nada que no esté escrito.
- Lo impreso (nombre de la empresa, CIF, direcciones de la empresa) NO es el cliente.
- Materiales que esta empresa usa a menudo (úsalos para entender la letra): cable 1000V, terminales, tuercas, clavijas 3P+T+N, bridas de hierro con collarín, juntas de goma, diferenciales, magnetotérmicos, tubo corrugado, cajas de registro, bombas sumergibles, cuadros de maniobra, sondas de nivel.
- La fecha es reciente (de este año o del anterior). Si el año no se lee claro, ponlo en "dudas".`;
const salida = [];
for (let i = 0; i < $input.all().length; i++) {
  const item = $input.all()[i];
  const clave = Object.keys(item.binary || {})[0];
  if (!clave) continue;
  const buf = await this.helpers.getBinaryDataBuffer(i, clave);
  salida.push({ json: { peticion: {
    contents: [{ parts: [{ text: instrucciones }, { inline_data: { mime_type: item.binary[clave].mimeType || 'image/jpeg', data: buf.toString('base64') } }] }],
    generationConfig: { temperature: 0, responseMimeType: 'application/json' },
  } } });
}
return salida;

const esc = (t) => String(t ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const euros = (n) => Number(n || 0).toLocaleString('es-ES', { minimumFractionDigits: 2, maximumFractionDigits: 2 }) + ' €';
const lista = (xs, f) => (xs || []).map(f).filter(Boolean).join(' · ');

return $input.all().map((item) => {
  const txt = item.json.candidates?.[0]?.content?.parts?.map((p) => p.text).join('') || '';
  let d; try { d = JSON.parse(txt.replace(/^```(json)?|```$/g, '').trim()); } catch { d = null; }
  if (!d) return { json: { telegram: '<b>⚠️ No he podido leer el parte de la foto.</b>\nPrueba con otra foto más recta y con luz.', fila: null } };
  const mats = lista(d.materiales, (m) => [m.cant, m.descripcion].filter(Boolean).join(' '));
  const mano = lista(d.mano_obra, (m) => [m.descripcion, m.horas ? m.horas + ' h' : ''].filter(Boolean).join(' '));
  const telegram = `<b>📷 Parte leído de la foto${d.numero ? ' · Nº ' + esc(d.numero) : ''}</b>\n` +
    `<b>Cliente:</b> ${esc(d.cliente || '¿?')} · ${esc(d.localidad || '')}\n<b>Fecha:</b> ${esc(d.fecha || '¿?')}\n\n<b>Materiales</b>\n` +
    (d.materiales || []).map((m) => `• ${esc(m.cant)} ${esc(m.descripcion)}${m.importe ? ' — ' + esc(m.importe) : ''}`).join('\n') +
    ((d.mano_obra || []).length ? `\n\n<b>Mano de obra</b>\n` + d.mano_obra.map((m) => `• ${esc(m.descripcion)} ${m.horas ? esc(m.horas) + ' h' : ''}`).join('\n') : '') +
    (d.dudas ? `\n\n<i>⚠️ Revisar: ${esc(d.dudas)}</i>` : '');
  const fila = { 'Nº': d.numero, 'Fecha': d.fecha, 'Hora': '', 'Trabajador': '', 'Cliente': d.cliente, 'NIF/CIF': d.nif, 'Localidad': d.localidad,
    'Trabajo': '', 'Materiales': mats, 'Mano de obra': mano, 'Total': '', 'Firmado por': '', 'Origen': 'Foto de parte en papel', 'Facturado': '' };
  return { json: { telegram, fila } };
});
